// Regenerates every brand asset from brand.json. Run with `npm run brand`.
// Generated files must not be edited by hand: change brand.json or a template instead.
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.join(here, '..');
const brand = JSON.parse(await readFile(path.join(here, 'brand.json'), 'utf8'));

// The mascot template and the generated tokens rely on these keys existing.
const REQUIRED_COLORS = [
  'ember',
  'emberDeep',
  'foxfire',
  'spirit',
  'cream',
  'night',
  'ink',
  'inkRaised',
  'line',
  'mist',
  'haze',
  'success',
  'warning',
  'danger',
];
for (const key of REQUIRED_COLORS) {
  if (!/^#[0-9a-f]{6}$/i.test(brand.colors[key]?.hex ?? '')) {
    throw new Error(`brand.json: colors.${key}.hex must be a 6-digit hex colour`);
  }
}

const kebab = (s) => s.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);
const escapeHtml = (s) =>
  s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const gradient = `linear-gradient(135deg, ${brand.gradient
  .map((key, i, all) => `${brand.colors[key].hex} ${Math.round((i / (all.length - 1)) * 100)}%`)
  .join(', ')})`;

function fill(template, values) {
  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => {
    if (!(key in values)) throw new Error(`Unknown placeholder {{${key}}}`);
    return values[key];
  });
}

const colorHexes = Object.fromEntries(
  Object.entries(brand.colors).map(([key, c]) => [key, c.hex.toUpperCase()]),
);
const text = {
  name: escapeHtml(brand.name),
  tagline: escapeHtml(brand.tagline),
  mascotName: escapeHtml(brand.mascotName),
};

const css = `/* Generated by brand/build.mjs from brand/brand.json. Do not edit. */
:root {
${Object.entries(colorHexes)
  .map(([key, hex]) => `  --brand-${kebab(key)}: ${hex.toLowerCase()};`)
  .join('\n')}

  --brand-gradient: ${gradient.toLowerCase()};

  --brand-font-display: '${brand.fonts.display}', 'Segoe UI', system-ui, sans-serif;
  --brand-font-body: '${brand.fonts.body}', 'Segoe UI', system-ui, sans-serif;
  --brand-radius: 14px;
}
`;

const ts = `// Generated by brand/build.mjs from brand/brand.json. Do not edit.
export const brand = ${JSON.stringify(
  {
    name: brand.name,
    domain: brand.domain,
    tagline: brand.tagline,
    // One tagline per website language; `tagline` above is the French one.
    taglines: { fr: brand.tagline, ...brand.taglines },
    mascotName: brand.mascotName,
    virtualCameraName: `${brand.name} Camera`,
    virtualMicrophoneName: `${brand.name} Microphone`,
    colors: colorHexes,
    fonts: brand.fonts,
  },
  null,
  2,
)} as const;

export type BrandColor = keyof typeof brand.colors;
`;

const swatches = [
  ...Object.values(brand.colors).map((c) => ({
    label: c.label,
    caption: c.hex.toUpperCase(),
    bg: c.hex,
  })),
  {
    label: 'Dégradé',
    caption: brand.gradient.map((key) => brand.colors[key].label).join(' → '),
    bg: gradient,
  },
]
  .map(
    (s) =>
      `        <div class="swatch"><i style="background: ${s.bg}"></i><div>${escapeHtml(s.label)}<code>${escapeHtml(s.caption)}</code></div></div>`,
  )
  .join('\n');

const mascot = fill(await readFile(path.join(here, 'mascot.template.svg'), 'utf8'), {
  ...colorHexes,
  ...text,
});
const board = fill(await readFile(path.join(here, 'brand-board.template.html'), 'utf8'), {
  ...text,
  swatches,
});

const outputs = {
  'shared/brand/tokens.css': css,
  'shared/brand/tokens.ts': ts,
  'docs/brand/mascot.svg': mascot,
  'docs/brand/brand-board.html': board,
  // The website keeps its own generated copies so it builds without reaching outside web/.
  'web/src/brand/tokens.css': css,
  'web/src/brand/tokens.ts': ts,
  'web/public/mascot.svg': mascot,
  'web/src/app/icon.svg': mascot,
  'desktop/src/brand/tokens.css': css,
  'desktop/src/brand/tokens.ts': ts,
  'desktop/public/mascot.svg': mascot,
};
for (const [file, content] of Object.entries(outputs)) {
  const target = path.join(root, file);
  await mkdir(path.dirname(target), { recursive: true });
  await writeFile(target, content);
  console.log(`wrote ${file}`);
}

// The desktop window and installer carry the product name. The identifier stays fixed on
// purpose: changing it would orphan installed copies and their saved sessions.
const tauriConfigPath = path.join(root, 'desktop/src-tauri/tauri.conf.json');
const tauriConfig = JSON.parse(await readFile(tauriConfigPath, 'utf8'));
tauriConfig.productName = brand.name;
tauriConfig.app.windows[0].title = brand.name;
await writeFile(tauriConfigPath, JSON.stringify(tauriConfig, null, 2) + '\n');
console.log('updated desktop/src-tauri/tauri.conf.json');
